import functools
import inspect
from typing import Dict, Any

def get_globalns(call: Any) -> Dict[str, Any]:
    unwrapped = inspect.unwrap(call)
    while isinstance(unwrapped, functools.partial):
        unwrapped = inspect.unwrap(unwrapped.func)

    if hasattr(unwrapped, "__globals__"):
        return unwrapped.__globals__
    if hasattr(unwrapped, "__call__") and hasattr(unwrapped.__call__, "__globals__"):
        return unwrapped.__call__.__globals__
    return {}

def my_func(a: int):
    return a

print(f"Regular func: {get_globalns(my_func) is my_func.__globals__}")

partial_func = functools.partial(my_func, a=1)
print(f"Partial func: {get_globalns(partial_func) is my_func.__globals__}")

nested_partial = functools.partial(partial_func, b=2)
print(f"Nested partial: {get_globalns(nested_partial) is my_func.__globals__}")

class MyCallable:
    def __call__(self, a: int):
        return a

callable_instance = MyCallable()
print(f"Callable instance: {get_globalns(callable_instance) is callable_instance.__call__.__globals__}")

partial_callable = functools.partial(callable_instance, a=1)
print(f"Partial callable: {get_globalns(partial_callable) is callable_instance.__call__.__globals__}")
", "filepath": "test_globals.py"}

